const whisperData = $('Process Whisper Response').first().json;
const responseData = $input.first().json;
const now = Date.now();
const totalMs = now - metadata._pipeline_start_ms;
const qwenMs = totalMs - whisperData._whisper_duration_ms;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `INSERT INTO voice_latency_metrics (client_type, audio_file_size_bytes, whisper_inference_ms, whisper_total_ms, qwen_inference_ms, total_pipeline_ms, whisper_model, qwen_model, language, transcript_length) VALUES ('${esc(metadata._client_type)}', ${metadata._audio_file_size || 0}, ${Math.round(whisperData._whisper_duration_ms)}, ${Math.round(whisperData._whisper_duration_ms)}, ${Math.round(qwenMs)}, ${Math.round(totalMs)}, 'large-v3-turbo-q5', 'qwen3-4b-voice', 'en', ${responseData.text?.length || 0})`;

return [{ json: { _query: query } }];

// ============================================================
// PREPARE AUDIO ARCHIVE (PLACEHOLDER)
// ============================================================
// WHAT: Prepares metadata for Nextcloud WebDAV upload.
// WHY:  Audio files archived to Nextcloud for training data review
//       and LoRA fine-tuning dataset export.
// STATUS: Placeholder -- Archive to Nextcloud node is a NoOp.
//         Configure when Nextcloud WebDAV access is set up.
// TARGET: AppsVM Nextcloud (YOUR_HOST_IP)
// ============================================================

// Pass through -- nothing to do until Nextcloud is configured
const metadata = $('Set Metadata').first().json;
const whisperData = $('Process Whisper Response').first().json;

const now = new Date();
const datePath = now.toISOString().split('T')[0]; // YYYY-MM-DD
const filename = `voice_${now.getTime()}.wav`;

return [{
  json: {
    _archive_path: `/STMNA_Voice/audio/${datePath}/${filename}`,
    _archive_status: 'placeholder_not_configured',
    _detected_language: whisperData.detected_language || 'unknown'
  }
}];

// ============================================================
// HALLUCINATION FILTER — Post-Whisper Cleanup
// ============================================================
// WHAT: Detects and handles common Whisper hallucination patterns
//       before passing to Qwen for polishing.
// WHY:  Whisper hallucinates on short/noisy audio — outputs random
//       phrases like "Thank you", "Tschüss", "Gracias" or even
//       wrong-alphabet text that was never spoken.
// HOW:  Five detection methods:
//       1. Known phantom phrases (YouTube training artifacts)
//       2. Non-Latin script detection (Japanese/Chinese/Arabic etc.)
//       3. Segment confidence from verbose_json (no_speech_prob)
//       4. Repetition detection (same phrase looping 3+ times)
//       5. Tail segment trimming (trailing phantoms / low-confidence)
// NEXT: Process Whisper Response gets clean transcript.
// ============================================================

const whisperResponse = $input.first().json;

// --- 1. KNOWN PHANTOM PHRASES ---
// Common Whisper artifacts from YouTube training data.
const PHANTOM_PHRASES = [
  'thank you', 'thanks', 'thanks for watching', 'thanks for listening',
  'thank you for watching', 'thank you for listening',
  'goodbye', 'bye', 'bye bye', 'bye-bye',
  'tschüss', 'tschuss', 'tschuess',
  'gracias', 'adiós', 'adios',
  'arrivederci', 'ciao',
  'okay', 'ok',
  'subtitles by', 'subtitled by', 'sous-titres',
  'please subscribe', 'like and subscribe',
  'see you next time', 'see you later', 'see you',
  'à bientôt', 'a bientot', 'au revoir',
  'you', 'the end', 'fin',
  '...',
  'thats good to meet you', 'nice to meet you',
  'merci', 'merci beaucoup', 'merci de votre attention',
  'cest bon de vous rencontrer',
];

const rawText = (whisperResponse.text || '').trim();
const normalized = rawText.toLowerCase().replace(/[.,!?…\-''`]+/g, '').trim();

const isPhantom = PHANTOM_PHRASES.some(p => normalized === p);

// --- 2. NON-LATIN SCRIPT DETECTION ---
const nonLatinPattern = /[\u3000-\u9FFF\uAC00-\uD7AF\u0600-\u06FF\u0400-\u04FF\u1100-\u11FF\uA960-\uA97F\uD7B0-\uD7FF\u3040-\u309F\u30A0-\u30FF\u31F0-\u31FF\uFF00-\uFFEF]/;
const hasNonLatin = nonLatinPattern.test(rawText);

// --- 3. SEGMENT CONFIDENCE CHECK ---
const segments = whisperResponse.segments || [];
let highNoSpeechCount = 0;
const totalSegments = segments.length;

for (const seg of segments) {
  if ((seg.no_speech_prob || 0) > 0.7) {
    highNoSpeechCount++;
  }
}
const allNoSpeech = totalSegments > 0 && highNoSpeechCount === totalSegments;

// --- 4. REPETITION DETECTION ---
let cleanedText = rawText;
const sentences = rawText.split(/[.!?]+/).map(s => s.trim()).filter(s => s.length > 0);
if (sentences.length >= 3) {
  const counts = {};
  for (const s of sentences) {
    const key = s.toLowerCase();
    counts[key] = (counts[key] || 0) + 1;
  }
  const repeated = Object.entries(counts).filter(([k, v]) => v >= 3);
  if (repeated.length > 0) {
    const seen = new Set();
    const deduped = [];
    for (const s of sentences) {
      const key = s.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        deduped.push(s);
      }
    }
    cleanedText = deduped.join('. ') + '.';
  }
}

// --- 5. TAIL SEGMENT TRIMMING ---
// Walk segments from the end. Strip if:
//   a) Segment text (normalized) matches a known phantom phrase, OR
//   b) Average word probability is below threshold (low confidence)
// Stop as soon as we hit a good segment.
// Only runs when there are 2+ segments (never strip the only segment).
const TAIL_PROB_THRESHOLD = 0.45;
let trimmedSegments = [];
let tailTrimmed = false;
let trimmedTexts = [];

if (segments.length >= 2) {
  let cutIndex = segments.length;
  for (let i = segments.length - 1; i >= 1; i--) {
    const seg = segments[i];
    const segText = (seg.text || '').trim();
    const segNorm = segText.toLowerCase().replace(/[.,!?…\-''`]+/g, '').trim();

    const isSegPhantom = PHANTOM_PHRASES.some(p => segNorm === p);

    let avgProb = 1.0;
    const words = seg.words || [];
    if (words.length > 0) {
      const sum = words.reduce((acc, w) => acc + (w.probability || 0), 0);
      avgProb = sum / words.length;
    }

    if (isSegPhantom || avgProb < TAIL_PROB_THRESHOLD) {
      cutIndex = i;
      trimmedTexts.push(segText + ' (phantom=' + isSegPhantom + ', avgProb=' + avgProb.toFixed(3) + ')');
    } else {
      break;
    }
  }

  if (cutIndex < segments.length) {
    trimmedSegments = segments.slice(0, cutIndex);
    tailTrimmed = true;
    cleanedText = trimmedSegments.map(s => (s.text || '').trim()).join(' ');
  }
}

// --- DECISION ---
let hallucination_detected = false;
let hallucination_type = null;
let finalText = cleanedText;

if (hasNonLatin) {
  hallucination_detected = true;
  hallucination_type = 'wrong_script';
  finalText = '';
} else if (isPhantom && (allNoSpeech || totalSegments <= 1)) {
  hallucination_detected = true;
  hallucination_type = 'phantom_phrase';
  finalText = '';
} else if (isPhantom && normalized.split(/\s+/).length <= 3) {
  hallucination_detected = true;
  hallucination_type = 'short_phantom';
  finalText = '';
} else if (allNoSpeech && totalSegments > 0) {
  hallucination_detected = true;
  hallucination_type = 'no_speech';
  finalText = '';
} else if (tailTrimmed) {
  hallucination_detected = true;
  hallucination_type = 'tail_trimmed';
} else if (cleanedText !== rawText) {
  hallucination_detected = true;
  hallucination_type = 'repetition_cleaned';
  finalText = cleanedText;
}

return [{
  json: {
    ...whisperResponse,
    text: finalText,
    segments: tailTrimmed ? trimmedSegments : whisperResponse.segments,
    _original_text: rawText,
    _hallucination_detected: hallucination_detected,
    _hallucination_type: hallucination_type,
    _tail_trimmed: tailTrimmed ? trimmedTexts : null,
  }
}];

